usage:
package main

import (
	"context"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	err := client.Realtime.Calls.Reject(
		context.TODO(),
		"call_id",
		openai.RealtimeCallRejectParams{
			StatusCode: param.NewOpt[int64](1),
		},
	)
	if err != nil {
		panic(err.Error())
	}
}
